using Godot;
using System;
using System.Linq;
public partial class MigrationScene {
 Node3D campLifeRoot;string campLifeSignature="";double campLifeScan;bool wasAtLivingCamp;double campWelcomeUntil;string campWelcome="";
 void CampStructureCondition(){
  foreach(var node in buildRoot.GetChildren().OfType<Node3D>()){
   if(!node.HasMeta("blueprint"))continue;string id=node.GetMeta("blueprint").AsString();var piece=game.Building.Pieces.FirstOrDefault(p=>p.Id==id);if(piece==null||ExpeditionGame.Distance(piece.X,piece.Z,Community.X,Community.Z)>35)continue;
   int wear=piece.Health/piece.Def.Durability<.5?2:piece.Health/piece.Def.Durability<.9?1:0;var marks=node.GetNodeOrNull<Node3D>("WearMarks");
   if(marks!=null&&marks.GetMeta("wear").AsInt32()==wear)continue;
   if(marks!=null){node.RemoveChild(marks);marks.QueueFree();}if(wear==0)continue;
   marks=new Node3D{Name="WearMarks"};marks.SetMeta("wear",wear);node.AddChild(marks);
   for(int i=0;i<wear*4;i++){float x=(float)((i%4-1.5)*piece.Def.W*.18),y=(float)(piece.Def.H*(.25+(i%3)*.22));bool flat=piece.Def.H<.5;var scar=Box(marks,new(x,flat?(float)piece.Def.H+.014f:y,flat?(float)((i%3-1)*piece.Def.D*.2):-(float)piece.Def.D*.5f-.014f),flat?new(.3f,.012f,.025f):new(.3f,.018f,.012f),new(.12f,.09f,.055f));scar.RotationDegrees=flat?new(0,(i%2==0?1:-1)*22,0):new(0,0,(i%2==0?1:-1)*22);}
  }
 }
 void CampLifeAction(){if(CoopClient||!JourneyEnabled||!AtCommunityCamp)return;int level=Community.Improvements;if(level>=3){game.Notice="The camp workyard is fully improved.";return;}if(!Community.Survivors.Any(n=>n.Member)||Community.Food<1||Community.Water<1||Community.Survivors.Where(n=>n.Member).Any(n=>!ExpeditionCommunity.Sheltered(Community.Bed(n,game.Building.Pieces),game.Building.Pieces))){game.Notice="House your residents and stock food and clean water first.";return;}if(game.Craft.BenchTier<level+1||game.Craft.UnlockedTier<level+1){game.Notice="Camp improvement requires workshop and exploration tier "+(level+1);return;}
  int[] cost=level==0?new[]{8,0,6,0,0,0,0}:level==1?new[]{12,8,0,4,0,0,0}:new[]{12,0,0,0,8,2,0};for(int i=0;i<7;i++)if(game.Craft.Materials[i]<cost[i]){game.Notice="Camp improvement needs "+cost[i]+" "+ExpeditionGame.ResourceNames[i];return;}
  game.Change(()=>{for(int i=0;i<7;i++)game.Craft.Materials[i]-=cost[i];Community.Improvements++;game.WorldDecision("camp/improvement/"+Community.Improvements,"Camp workyard improved / "+new[]{"","personal spaces","communal hearth","organized workshop"}[Community.Improvements]);game.Notice="Camp improved / shared spaces, steadier morale and more effective work.";});FeverSync();
 }
 void ShowCampLife(){var b=Panel("HOME / THE PEOPLE YOU COME BACK TO");coopMenu="camplife";Text(b,$"Improvement {Community.Improvements}/3 / {Community.Survivors.Count(n=>n.Member)} residents\nFood {Community.Food} / clean water {Community.Water}\nPersonal belongings appear beside assigned beds. Residents gather around the hearth in the evening. Their work and greetings reflect food, shelter and injuries.");Text(b,Community.Improvements switch{0=>"Next: personal spaces / workshop 1 / 8 timber + 6 fiber.",1=>"Next: communal hearth / workshop 2 / 12 timber + 8 stone + 4 resin. Stocked hearths help you dry and warm up within 10m.",2=>"Next: organized workyard / workshop 3 / 12 timber + 8 alloy + 2 electronics.",_=>"Camp fully improved. Maintain shelter and stores; injury, hunger and damaged beds still affect your residents."});Text(b,"Each stage improves the resident morale target by 3 and work rate by 5%. You still build the shelter and maintain its condition. Decoration grants no structural support or zombie immunity.");Button(b,"BUILD THE NEXT CAMP IMPROVEMENT",()=>{if(!CoopRequest("camplife"))CampLifeAction();ShowCampLife();});Button(b,"CAMP STORIES / THE SUNDAY FIRE",ShowCampStories);Button(b,"PLAN AN EXPEDITION",ShowJourneyPlanner);Button(b,"COMMUNITY",()=>ShowCommunity());Button(b,"BACK",CloseMenu);}
 void DrawCampLife(double dt){if(!JourneyEnabled)return;if(campLifeRoot!=null&&!GodotObject.IsInstanceValid(campLifeRoot)){campLifeRoot=null;campLifeSignature="";}bool near=dungeon==null&&Community.Established&&ExpeditionGame.Distance(player.Position.X,player.Position.Z,Community.X,Community.Z)<120;
  if(campLifeRoot!=null)campLifeRoot.Visible=near;if(!near){wasAtLivingCamp=false;return;}bool home=AtCommunityCamp;
  if(home&&!wasAtLivingCamp&&!paused&&!infected.Any(e=>e.Memory>0&&Distance(e.Body.Position,player.Position)<25)){var person=Community.Survivors.FirstOrDefault(n=>n.Member&&!n.Downed&&string.IsNullOrEmpty(n.Owner));if(person!=null){campWelcome=person.Name+": "+(Community.Food<=0?"We stretched the last meal. We need food.":person.Injury>40?"I could use a quiet day. My injuries are slowing me down.":game.Life.Health<40?"You're hurt. Sit down; you're home now.":game.Life.Journey?.Recovered==true?"You brought something back. Let's sort it together.":person.GriefRemaining>0?"It feels too quiet without "+person.GrievingFor+". Stay a while, if you can.":Community.Improvements>=2?"The fire is going. Saved you a place.":"Good to see you back. We kept things going.");campWelcomeUntil=game.Clock+8;game.Notice=campWelcome;}}wasAtLivingCamp=home;
  campLifeScan-=dt;if(campLifeScan>0)return;campLifeScan=2;CampStructureCondition();string signature=Community.Losses.Count+"/"+Community.Gathering+"/"+game.Save.Seed+"/"+Community.Improvements+"/"+Community.Food/5+"/"+Community.Water/5+string.Join("/",Community.Survivors.Where(n=>n.Member).Select(n=>n.Id+n.BedId+(Community.Bed(n,game.Building.Pieces)?.Health??0)+ExpeditionCommunity.Sheltered(Community.Bed(n,game.Building.Pieces),game.Building.Pieces)));
  if(signature==campLifeSignature&&campLifeRoot!=null)return;campLifeSignature=signature;campLifeRoot?.QueueFree();campLifeRoot=new Node3D{Name="CampPersonalSpaces"};worldRoot.AddChild(campLifeRoot);
  foreach(var n in Community.Survivors.Where(n=>n.Member)){var bed=Community.Bed(n,game.Building.Pieces);if(bed==null)continue;var space=new Node3D{Position=new((float)bed.X,(float)bed.Y,(float)bed.Z),RotationDegrees=new(0,(float)bed.Yaw,0)};campLifeRoot.AddChild(space);Color color=n.Encounter==0?new(.48f,.26f,.18f):n.Encounter==1?new(.24f,.40f,.48f):new(.48f,.42f,.22f);Box(space,new(0,.52f,0),new(.7f,.03f,1.1f),color);Bevel(space,new(.78f,.3f,.3f),new(.3f,.6f,.35f),Wood);Tube(space,new(.78f,.62f,.3f),new(.78f,.73f,.3f),.045f,Steel);if(Community.Improvements>0){Box(space,new(-.76f,.18f,-.3f),new(.32f,.36f,.4f),color);for(int i=0;i<3;i++)Box(space,new(-.78f,.38f+i*.025f,-.3f),new(.18f,.02f,.25f),new(.55f,.49f,.34f));}space.AddChild(new Label3D{Text=n.Name+"'s corner",Position=new(0,1.2f,.7f),FontSize=18,PixelSize=.004f,Billboard=BaseMaterial3D.BillboardModeEnum.Enabled});}
  if(Community.Improvements>=2){var hearth=new Node3D{Position=Ground(Community.X+4,Community.Z+4)};campLifeRoot.AddChild(hearth);for(int i=0;i<9;i++){float a=i*Mathf.Tau/9;Ellipsoid(hearth,new(Mathf.Sin(a)*.65f,.15f,Mathf.Cos(a)*.65f),new(.19f,.14f,.17f),new(.35f,.37f,.34f));}if(Community.Food>0||Community.Gathering){Ellipsoid(hearth,new(0,.25f,0),new(.23f,.32f,.23f),new(.85f,.34f,.08f));hearth.AddChild(new OmniLight3D{Position=new(0,.6f,0),LightColor=new(1,.52f,.2f),LightEnergy=1.4f,OmniRange=9});}for(int side=-1;side<=1;side+=2)Bevel(hearth,new(side*1.5f,.28f,0),new(.35f,.5f,1.8f),Wood);}
  for(int i=0;i<Community.Losses.Count;i++){var loss=Community.Losses[i];var marker=new Node3D{Position=Ground(Community.X-3+i*1.3,Community.Z+7)};campLifeRoot.AddChild(marker);Box(marker,new(0,.4f,0),new(.42f,.8f,.10f),Wood);Box(marker,new(0,.8f,0),new(.52f,.08f,.13f),Steel);marker.AddChild(new Label3D{Text=loss.Name+"\nRemembered / day "+loss.Day,Position=new(0,1.15f,0),FontSize=22,PixelSize=.005f,Billboard=BaseMaterial3D.BillboardModeEnum.Enabled,Modulate=new(.85f,.79f,.63f)});Tube(marker,new(.23f,.05f,.2f),new(.23f,.32f,.2f),.012f,new(.24f,.39f,.20f));Ellipsoid(marker,new(.23f,.34f,.2f),new(.07f,.04f,.07f),new(.71f,.62f,.30f));}
  if(Community.Improvements>=3){var table=new Node3D{Position=Ground(Community.X-4,Community.Z+4)};campLifeRoot.AddChild(table);ArtWorkbench(table);for(int i=0;i<Math.Min(5,Community.Food/5);i++)Bevel(table,new(i*.28f-.6f,1.1f,0),new(.2f,.18f,.25f),new(.38f,.42f,.23f));}
 }
